  width: max-content;
  min-width: 100%;
}
.gridRow {
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.gridHead {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--v4-paper);
  min-height: var(--v4-size-control-sm);
  border-bottom: var(--v4-size-control-border) solid var(--v4-line);
  color: var(--v4-muted);
}
.gridHeader {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0;
  border-right: var(--v4-size-control-border) solid var(--v4-line-soft);
  padding: 0 var(--v4-space-12) 0 0;
  overflow: visible;
}
.gridHeader[data-selected] {
  background: var(--v4-select);
  color: var(--v4-ink);
}
.gridHeaderLabel {
  display: flex;
  flex: 1;
  min-width: 0;
  align-items: center;
  gap: var(--v4-space-6);
  padding-inline: var(--v4-space-8);
  overflow: hidden;
}
.gridHeaderLabel > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gridHeader small {
  min-width: 0;
  overflow: hidden;
  color: var(--v4-muted);
  font-size: inherit;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gridHeader button[data-active] {
  color: var(--v4-ink);
}
.gridHeader button > svg {
  width: var(--v4-size-icon-xs);
  height: var(--v4-size-icon-xs);
}
.gridHeader button {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: var(--v4-space-24);
  height: var(--v4-space-24);
  background: none;
  border: 0;
  color: inherit;
  cursor: pointer;
}
.gutter {
  position: sticky;
  left: 0;
  z-index: 1;
  background: var(--v4-surface);
  padding: var(--v4-space-6) var(--v4-space-8);
  min-width: var(--v4-space-40);
  text-align: right;
  color: var(--v4-faint);
  border-right: var(--v4-size-control-border) solid var(--v4-line);
}
.gridHead > .gutter {
  background: inherit;
}
.gutter[data-selected] {
  background: var(--v4-select);
  color: var(--v4-ink);
}
.gutter button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  cursor: pointer;
}
.gridCell {
  padding: var(--v4-space-6) var(--v4-space-8);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  border-right: var(--v4-size-control-border) solid var(--v4-line-soft);
  position: relative;
}
.gridRow:hover > .gridCell:not([data-selected], [data-dirty]) {
  background: color-mix(in oklab, var(--v4-tint) 60%, transparent);
}
.gridCell[data-selected] {
  background: var(--v4-accent-wash);
}
.gridNull {
  color: var(--v4-faint);
  font-style: italic;
}
.gridCell[data-dirty] {
  background: var(--v4-warn-wash);
}
.gridCell[data-active] {
  outline: 2px solid var(--v4-ink);
  outline-offset: -2px;
}
.gridCell textarea {
  font: inherit;
  color: inherit;
  background: var(--v4-surface);
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  resize: none;
  border: 0;
  outline: 2px solid var(--v4-ink);
  outline-offset: -2px;
  padding: var(--v4-space-6);
}
.gridCell textarea[aria-invalid="true"] {
  outline-color: var(--v4-bad);
}
.resize {
  position: absolute;
  top: 0;
  bottom: 0;
  right: calc(-1 * (var(--v4-space-12) + var(--v4-size-control-border)));
  z-index: 1;
  width: var(--v4-space-24);
  cursor: col-resize;
  touch-action: none;
}
.resize::after {
  content: "";
  position: absolute;
  inset-block: 0;
  left: calc(50% - var(--v4-size-control-border));
  width: var(--v4-size-control-border);
  background: transparent;
  pointer-events: none;
  transition: background-color var(--v4-duration-fast) var(--v4-ease-fade);
}
.resize:hover::after {
  background: var(--v4-control);
}
.resize:focus-visible {
  outline: 2px solid var(--v4-ink);
  outline-offset: -2px;
}
.status {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: var(--v4-muted);
  padding: var(--v4-space-8) 0 0;
  overflow-wrap: anywhere;
}
.actions {
  display: flex;
  align-items: center;
  gap: var(--v4-space-12);
  flex-wrap: wrap;
  padding: var(--v4-space-12) 0 0;
}
.actions [role="alert"] {
  color: var(--v4-bad);
}
.empty {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  padding: var(--v4-space-surface-inset-sm);
  color: var(--v4-muted);
}
.editor {
  display: grid;
  gap: var(--v4-space-8);
  min-width: 0;
  color: var(--v4-ink);
}
.label {
  font-family: var(--v4-type-field-label-font-family);
  font-size: var(--v4-type-field-label-font-size);
